import sys, os, csv, json, math, re
from datetime import *

d = []
t = 0
t2 = 0
r = {}
p = {}
n = 0


def parse_args(argv):
    filename = None
    fmt = "text"
    since = None
    i = 1
    while i < len(argv):
        a = argv[i]
        if a == "--format":
            i = i + 1
            if i >= len(argv):
                sys.stderr.write("error: --format requires a value\n")
                sys.exit(2)
            fmt = argv[i]
        elif a.startswith("--format="):
            fmt = a.split("=", 1)[1]
        elif a == "--since":
            i = i + 1
            if i >= len(argv):
                sys.stderr.write("error: --since requires a value\n")
                sys.exit(2)
            since = argv[i]
        elif a.startswith("--since="):
            since = a.split("=", 1)[1]
        elif filename is None:
            filename = a
        else:
            sys.stderr.write("error: unexpected argument: " + a + "\n")
            sys.exit(2)
        i = i + 1
    if filename is None:
        sys.stderr.write("usage: python report.py sales.csv [--format text|json] [--since YYYY-MM-DD]\n")
        sys.exit(2)
    if fmt not in ("text", "json"):
        sys.stderr.write("error: --format must be text or json\n")
        sys.exit(2)
    if since is not None:
        try:
            since = datetime.strptime(since, "%Y-%m-%d").date()
        except:
            sys.stderr.write("error: --since must be YYYY-MM-DD\n")
            sys.exit(2)
    return filename, fmt, since


def go():
    global d, t, t2, r, p, n
    filename, fmt, since = parse_args(sys.argv)
    f = open(filename)
    lines = f.readlines()
    for i in range(len(lines)):
        if i == 0:
            continue
        l = lines[i].strip().split(",")
        if len(l) < 5:
            continue
        if since is not None:
            try:
                rowdate = datetime.strptime(l[0], "%Y-%m-%d").date()
            except:
                continue
            if rowdate < since:
                continue
        try:
            u = int(l[3])
        except:
            continue
        try:
            pr = float(l[4])
        except:
            continue
        amt = u * pr
        if u >= 50:
            amt = amt - amt * 0.1
        else:
            if u >= 10:
                amt = amt - amt * 0.05
        if l[1] == "north":
            tx = amt * 0.07
        elif l[1] == "south":
            tx = amt * 0.05
        elif l[1] == "east":
            tx = amt * 0.06
        elif l[1] == "west":
            tx = amt * 0.08
        else:
            tx = 0
        t = t + amt
        t2 = t2 + tx
        if l[1] in r:
            r[l[1]] = r[l[1]] + amt
        else:
            r[l[1]] = amt
        if l[2] in p:
            p[l[2]] = p[l[2]] + amt
        else:
            p[l[2]] = amt
        d.append(l)
        n = n + 1
    best = None
    bv = 0
    for k in p:
        if p[k] > bv:
            bv = p[k]
            best = k
    if fmt == "json":
        out = {}
        out["rows"] = n
        out["total_revenue"] = round(t, 2)
        out["total_tax"] = round(t2, 2)
        out["by_region"] = dict((k, round(r[k], 2)) for k in sorted(r.keys()))
        out["by_product"] = dict((k, round(p[k], 2)) for k in sorted(p.keys()))
        out["top_product"] = best
        print(json.dumps(out))
        return
    print("SALES REPORT")
    print("============")
    print("Rows: " + str(n))
    print("Total revenue: " + str(round(t, 2)))
    print("Total tax: " + str(round(t2, 2)))
    print("")
    print("By region:")
    for k in sorted(r.keys()):
        print("  " + k + ": " + str(round(r[k], 2)))
    print("")
    print("By product:")
    for k in sorted(p.keys()):
        print("  " + k + ": " + str(round(p[k], 2)))
    print("")
    print("Top product: " + best + " (" + str(round(bv, 2)) + ")")


go()
